  "ARCH 2016": {"name": "Architecture Design Studio 2", "hours": 5, "description": "Elementary design exercises exploring fundamental issues of form and space through analysis of architectural elements and compositions and their use in creative problem solving."},
  "ARCH 2017": {"name": "Architecture Design Studio 3", "hours": 5, "description": "Elementary design exercises focusing upon the compositional integration of building and site through the creative assimilation of programmatic, technical, and contextual requirements."},
  "ARCH 2020": {"name": "Media + Modeling 2", "hours": 3, "description": "Advanced approaches to two and three dimensional modeling and representation in architecture using both manual and digital media and techniques."},
  "ARCH 2111": {"name": "History of Architecture I", "hours": 3, "description": "Architectural history from antiquity through the eighteenth century emphasizing buildings in their cultural context as informed by social, technological, and constructive factors and theoretical positions."},
  "ARCH 2112": {"name": "History of Architecture II", "hours": 3, "description": "Architectural history during the nineteenth and twentieth centuries emphasizing buildings in their cultural context as informed by social, technological, and constructive factors and theoretical positions."},
  "ARCH 2211": {"name": "Construction Technology and Design Integration I", "hours": 3, "description": "Introduction to building anatomy, technical and expressive characteristics of materials and their organizational assembly."},
