  "BMED 4893": {"name": "Special Topics", "hours": 3, "description": "Special Topics in BMED."},
  "BMED 4900": {"name": "Special Problems", "hours": 1, "description": "Individualized studies in certain specialized areas of interest in biomedical engineering."},
