  "CHIN 1001": {"name": "Elementary Chinese I", "hours": 4, "description": "Introduction to listening, speaking, reading, and writing in Chinese (Mandarin) and to the culture of Chinese-speaking regions."},
  "CHIN 1002": {"name": "Elementary Chinese II", "hours": 4, "description": "Continued listening, speaking, reading, and writing in Chinese (Mandarin) with further study of the culture of Chinese-speaking regions."},
  "CHIN 1011": {"name": "Accelerated Elementary Chinese I", "hours": 4, "description": "This is the first of two courses in the basic Chinese sequence geared for heritage learners at the elementary level. The pace is approximately 30% faster than the non-accelerated course."},
  "CHIN 10X1": {"name": "Trans Elementary Chinese I", "hours": 3, "description": ""},
  "CHIN 10X2": {"name": "Trans Elementary Chinese II", "hours": 3, "description": ""},
  "CHIN 1501": {"name": "Chinese for Heritage Learners I", "hours": 3, "description": "For heritage students in the U.S. who have never studied Chinese formally, but who speak some Chinese without being able to read or write it. Taught in Chinese."},
  "CHIN 1XXX": {"name": "Chinese Elective", "hours": 1, "description": ""},
  "CHIN 2001": {"name": "Intermediate Chinese I", "hours": 3, "description": "A rapid review of grammar with continued use of listening, speaking, reading, and writing skills in Chinese (Mandarin), all with a cultural emphasis."},
  "CHIN 2002": {"name": "Intermediate Chinese II", "hours": 3, "description": "This course focuses on listening, speaking, reading, and writing skills in Chinese (Mandarin) in an introduction to literature and within a cultural context."},
  "CHIN 2501": {"name": "Chinese For Heritage Learners II", "hours": 3, "description": "For intermediate-level heritage students in the U.S. who can communicate some in Chinese, but cannot read or write it for academic purposes. Taught in Chinese."},
  "CHIN 2XXX": {"name": "Chinese Elective", "hours": 1, "description": ""},
  "CHIN 3003": {"name": "Intermediate Chinese III", "hours": 3, "description": "Continued reinforcement of basic speaking, reading, and writing skills, and cultural knowledge to enhance students' communication ability in topics relating to contemporary life and Chinese society."},
  "CHIN 3004": {"name": "Advanced Chinese I", "hours": 3, "description": "Continued reinforcement of intermediate speaking, reading, and writing skills, and cultural knowledge to enhance students' communication ability in topics relating to contemporary life and Chinese society."},
  "CHIN 3021": {"name": "Chinese Society and Culture I", "hours": 3, "description": "Comprehension and discussion of issues in contemporary Chinese culture."},
  "CHIN 3022": {"name": "Chinese Society and Culture II", "hours": 3, "description": "Comprehension and discussion of Chinese news, economic reports, political events, feature stories, and sports on television and in newspapers."},
  "CHIN 3100": {"name": "Chinese Food Culture", "hours": 3, "description": "This course explores the cultural, sociopolitical, technological, and environmental significance of food in Chinese history. Taught in Chinese."},
  "CHIN 3400": {"name": "China: A Cultural Odyssey", "hours": 3, "description": "Key aspects of culture and highlights of Chinese civilization: philosophy, arts and architecture, belief systems, family relationships, historical periods, social changes, technological innovation. Taught in English."},
  "CHIN 3401": {"name": "A Kaleidoscope of Chinese Language", "hours": 3, "description": "Explores the Chinese language from multiple perspectives, examining its multifaceted and intriguing interactions with society, culture, gender, music, politics, and media. Taught in English."},
  "CHIN 3691": {"name": "Chinese for Current Events", "hours": 3, "description": "Reading, discussion and analysis of intermediate/advanced current events texts and authentic media. Part of the intensive summer Chinese language program (LBAT). Admission by application only."},
  "CHIN 3692": {"name": "Business Chinese", "hours": 3, "description": "Acquisition of business technology, protocols, decorum strategies and improvement of oral communication skills. Reading and writing of notes, correspondence, and reports. Part of the summer language program (LBAT). Admission by application only."},
  "CHIN 3693": {"name": "Conversation Practicum (LBAT)", "hours": 3, "description": "Language practicum in the local community with written and oral classroom presentations. Part of the intensive summer Chinese language program (LBAT). Admission by application only."},
  "CHIN 3696": {"name": "Economic Development and Sustainability in China", "hours": 3, "description": "Examines the world's most populous nation's assault on its environment and resources in the pursuit of rapid economic growth. Taught in Chinese."},
  "CHIN 3813": {"name": "Special Topics", "hours": 3, "description": "Permits a group of students and a professor to pursue areas of the Chinese language not extensively treated in other courses in the department."},
  "CHIN 3XXX": {"name": "Advanced Chinese Credit", "hours": 3, "description": "Advanced-level generic Chinese language credit."},
  "CHIN 4003": {"name": "Advanced Chinese II: Contemporary China", "hours": 3, "description": "Development of advanced communication abilities. Materials deal with the economic, cultural, social, and political changes in contemporary China. Taught in Chinese."},
  "CHIN 4004": {"name": "Advanced Chinese III: Contemporary China", "hours": 3, "description": "Further development of advanced communication abilities. Materials deal with the economic, cultural, social, and political changes in contemporary China. Taught in Chinese."},
  "CHIN 4021": {"name": "Advanced Language, Popular Music and Culture", "hours": 3, "description": "Utilizing popular songs/videos as cultural texts, this advanced language and culture course develops the students' listening, reading, writing, presentation, and web-based research in Chinese."},
  "CHIN 4022": {"name": "Kungfu Fiction/Pop Cul", "hours": 3, "description": "Utilizing authentic kungfu fiction texts, this advanced language and culture course develops students' listening, reading, writing, presentation, and web-based research, all in Chinese."},
  "CHIN 4031": {"name": "Chinese-Language Cinema: Technological, Cultural, and Urban Transformation in China", "hours": 3, "description": "Utilizing selected Chinese films as texts, this advanced Chinese course analyzes and discusses the technological, cultural, and urban transformation in China."},
  "CHIN 4032": {"name": "Kungfu and Wuxia Film and Pop Culture", "hours": 3, "description": "Utilizing authentic film texts, this advanced language/culture course develops the students; listening, reading, writing, presentation, and web-based research abilities and skills in Chinese."},
  "CHIN 4500": {"name": "Advanced Intercultural Seminar", "hours": 3, "description": "Integrates cross-cultural research and reflection into discussion of current issues in the Chinese-speaking world. Intended for students who have had some study-abroad experience in China. Conducted in Chinese."},
  "CHIN 4695": {"name": "Chinese Internship", "hours": 1, "description": "Professional experience with a business/organization in which students enhance their language skills and cultural knowledge in Chinese in relation to the practical goals/objectives of the entity."},
  "CHIN 4698": {"name": "Undergraduate Research Assistantship", "hours": 1, "description": "Independent research conducted under the guidance of a faculty member."},
  "CHIN 4699": {"name": "Undergraduate Research", "hours": 1, "description": "Independent research conducted under the guidance of a faculty member."},
