  "CP 4812": {"name": "Special Topics", "hours": 2, "description": "Topics of current interest not covered in other courses in the department."},
  "CP 4813": {"name": "Special Topics", "hours": 3, "description": "Topics of current interest not covered in other courses in the department."},
  "CP 4815": {"name": "Special Topics", "hours": 5, "description": "Topics of current interest not covered in other courses in the department."},
