  "CP 8901": {"name": "Special Problems", "hours": 1, "description": "Special problems of current interest."},
  "CP 8902": {"name": "Special Problems", "hours": 1, "description": "Special problems of current interest."},
  "CP 8990": {"name": "Applied Research Paper", "hours": 1, "description": "The applied research paper requires students to demonstrate their ability to organize and execute professional-level work in consultation with a faculty member."},
  "CP 8997": {"name": "Teaching Assistantship", "hours": 1, "description": "For graduate students holding graduate teaching assistantships."},
  "CP 8998": {"name": "Research Assistantship", "hours": 1, "description": "For graduate students holding graduate research assistantships."},
