  "ECE 2XXX": {"name": "Electrical and Computer Engineering Elective", "hours": 1, "description": ""},
  "ECE 3005": {"name": "Professional and Technical Communications Practicum for ECE", "hours": 1, "description": "Written, oral, and visual communication skills required by electrical and computer engineers. Prepares students for advanced communication tasks required in academic and professional settings."},
  "ECE 3011": {"name": "ECE Design Fundamentals", "hours": 2, "description": "This course teaches system-level design, including both software and hardware. Through activities and projects, students gain exposure to entrepreneurship, product lifecycle management, prototyping, and testing."},
  "ECE 3025": {"name": "Electromagnetics", "hours": 3, "description": "To present the laws and applications of electromagnetics."},
  "ECE 3030": {"name": "Physical Foundations of Computer Engineering", "hours": 3, "description": "Basic principles governing the physical realization of computing systems and their relationship to characteristics such as performance, energy, and robustness. Implementation technologies."},
  "ECE 3040": {"name": "Microelectronic Circuits", "hours": 4, "description": "Basic concepts of microelectronic materials, devices, and circuits."},
  "ECE 3040R": {"name": "ECE 3040 Recitation", "hours": 0, "description": "ECE 3040 Recitation."},
  "ECE 3043": {"name": "Measurements, Circuits, and Microelectronics Laboratory", "hours": 2, "description": "Basic electronic test instrumentation. Elementary passive and active circuits using both discrete (diodes, bipolar junction transistors, MOSFETs) and integrated devices (operational amplifiers). Credit not allowed for both ECE 3043 and ECE 3041."},
  "ECE 3058": {"name": "Architecture, Systems, Concurrency, and Energy in Computation", "hours": 4, "description": "Basic organizational principles of the major components of a processor \u2013 the core, memory hierarchy, I/O subsystem and basic operating system constructs that utilize them."},
  "ECE 3072": {"name": "Electrical Energy Systems", "hours": 3, "description": "Non-renewable and renewable/sustainable energy sources. Processes, costs, and environmental impact of conversion into electric energy. Delivery and control of electric energy, electromechanical systems. Credit not allowed for both ECE 3072 and ECE 3071."},
  "ECE 3077": {"name": "Introduction to Probability and Statistics for ECE", "hours": 3, "description": "Introduction to probability, random variables, distributions, estimation, confidence intervals, linear regression and other tools for describing and managing uncertainty in electrical and computer engineering."},
  "ECE 3084": {"name": "Signals and Systems", "hours": 3, "description": "Continuous-time linear systems and signals, their mathematical representations, and computational tools. Fourier and Laplace transforms, convolutions, input-output responses, stability."},
  "ECE 3150": {"name": "VLSI and Advanced Digital Design", "hours": 4, "description": "Advanced digital design issues in the context of VLSI systems. Introduction to a design methodolgy that encompasses the range from architectural models to circuit simulation. Credit not awarded for ECE 3150 and ECE 3060."},
  "ECE 3170": {"name": "Cryptographic Hardware for Embedded Systems", "hours": 4, "description": "Introduction to cryptography and authentication from a hardware-centric perspective. Historic ciphers, symmetric and asymmetric encryption, and power analysis attacks are taught from a digital and VLSI design perspective."},
  "ECE 3251": {"name": "Optimization for Information Systems", "hours": 3, "description": "An introduction to the fundamentals of optimization with a focus on algorithms and applications in signal processing, control systems, machine learning, and robotics."},
  "ECE 3300": {"name": "Electromechanical and Electromagnetic Energy Conversion", "hours": 3, "description": "Introduction to three phase power systems, electromechanical energy conversion and operating principles of electric machines."},
  "ECE 3400": {"name": "Analog Electronics", "hours": 3, "description": "Analysis and design of electronic circuits and systems. Biasing, small-signal analysis, frequency response, feedback amplifiers, active filters, non-linear op-amp applications, and oscillators."},
  "ECE 3450": {"name": "Semiconductor Devices", "hours": 3, "description": "Properties of semiconductor devices. Applications in current and future computers, fiber optic and wireless communication systems. Future needs of high frequency, GHz-range, device operation."},
  "ECE 3550": {"name": "Feedback Control Systems", "hours": 3, "description": "Analysis and design of control systems. Laplace transforms, transfer functions, and stability. Feedback systems: tracking and disturbance rejection. Graphical design techniques."},
  "ECE 3600": {"name": "Computer Communications", "hours": 3, "description": "Basic concepts of computer communication network protocols."},
  "ECE 3710": {"name": "Circuits and Electronics", "hours": 2, "description": "An introduction to electric circuit elements and electronic devices and a study of circuits containing such devices."},
  "ECE 3741": {"name": "Instrumentation and Electronics Lab", "hours": 1, "description": "Basic analog and digital electronic circuits and principles. Techniques of electrical and electronic measurements with laboratory instruments."},
