  "FREN 6011": {"name": "French Art", "hours": 3, "description": "This course will thematically explore French visual, conceptual, and performance art in the historical, theoretical, and cultural contexts of production and reception."},
  "FREN 6013": {"name": "Literature &amp; Visual Arts", "hours": 3, "description": "This course examines the relationship between Word and Image (including cinema/ film adaptations, photography, hypertext, graphic design, and diverse artistic genres). Taught in French."},
  "FREN 6064": {"name": "Sustainability &amp; Development in the Francophone World", "hours": 3, "description": "This course will analyze current sustainability &amp; development issues in the Francophone World, and policies initiated to address them. Taught in French."},
  "FREN 6089": {"name": "FOOD, ARTS &amp; MEDIA", "hours": 3, "description": "This course will focus on the culture of food in French arts, literature and media, examining its social and symbolic values through the centuries. In French."},
  "FREN 6101": {"name": "Contemporary Francophone Literature", "hours": 3, "description": "This course will analyze Francophone Literatures produced outside of France since 1960 with a focus on their modern and innovative aspects. Taught in French."},
  "FREN 6103": {"name": "Francophone Africa", "hours": 3, "description": "This interdisciplinary course will explore contemporary Francophone Africa and its representations in light of its modern history and culture. Taught in French."},
  "FREN 6105": {"name": "Francophone Cinema", "hours": 3, "description": "This course will explore through films representations of Francophone regions of the world from Africa to the Caribbean. Taught in French."},
  "FREN 6202": {"name": "SCIENCE IN THE FRENCH IMAGINATION", "hours": 3, "description": "This course explores the relationships between literature and science, culture, and technology from the late 18th to the 21st century. Taught in French."},
  "FREN 6252": {"name": "French Domestic Internship", "hours": 1, "description": "Students complete domestic internships. Conducted in French. Online course."},
  "FREN 6300": {"name": "France and Globalization", "hours": 3, "description": "Intercultural class about French attitudes and policies toward globalization as well as France's role in the European Community. Conducted in French."},
  "FREN 6500": {"name": "Intercultural Seminar", "hours": 3, "description": "Integrates cross-cultural research and reflection into discussion of current issues in the French-speaking world. Taught in French."},
  "FREN 6503": {"name": "Professional Portfolio Development", "hours": 3, "description": "Preparation of a professional portfolio connecting experiences and coursework in the MS program towards career preparation. Conducted in French."},
  "FREN 6510": {"name": "Applied Language Practicum", "hours": 3, "description": "Students will serve as researchers, student aides and apprentice instructors for any 3/4000-level undergraduate course approved by their adviser and the course."},
  "FREN 6511": {"name": "Applied Language Practicum Abroad", "hours": 3, "description": "Students serve as researchers and apprentice instructors in the LBAT or other faculty-led overseas language immersion program of the School of Modern Languages."},
  "FREN 6696": {"name": "French Internship Abroad", "hours": 1, "description": "Students complete internships abroad in a French-speaking country. Conducted in French. Online course."},
