  "GRMN 8903": {"name": "Special Problems in German", "hours": 1, "description": "Provides the special instruction required under special programs."},
  "GT 0900": {"name": "Challenge Summer Intensive Residential Program: Interpersonal Development Course", "hours": 2, "description": "Challenge is a summer residential program for incoming freshman. This course provides critical skills and competencies for the interpersonal and communication development components of Challenge."},
  "GT 1000": {"name": "First-Year Seminar", "hours": 1, "description": "Discussion of topics related to academic, social and professional success including learning styles, time management, major and career exploration, leadership and teamwork."},
  "GT 1201": {"name": "Exploring Grand Challenges", "hours": 3, "description": "A problem-based learning approach to developing problem solving skills for multidisciplinary teams of freshmen to tackle Grand Challenges facing humanity."},
  "GT 1801": {"name": "Special Topics", "hours": 1, "description": "Discussion of topics related to scholarship, leadership, progress, and service focusing on helping students to make impacts those arenas on and beyond campus."},
  "GT 2000": {"name": "Transfer Student Seminar", "hours": 1, "description": "Discussion of topics related to academic, social and professional success including learning styles, time management, major and career exploration, leadership and teamwork."},
  "GT 2030": {"name": "Progress &amp; Service Forum", "hours": 3, "description": "Foundational course for Leaders in Progress and Service Program. An introduction to defining complex problems, concepts of professional identity, and roles of professionals in society."},
  "GT 2100": {"name": "Student Success Seminar", "hours": 1, "description": "This academic skills seminar is designed to help students develop personalized strategies for success within the rigorous academic environment at Georgia Tech. This course cannot be used toward degree requirements."},
  "GT 2201": {"name": "Grand Challenges Research Project", "hours": 1, "description": "This course is for participants in year 2 of the Grand Challenges program. Students will organize into small teams of 4-8 student to pursue research and development projects that were approved and funded in year 1. Participating students can also propose new projects."},
  "GT 2202": {"name": "Grand Challenges Research Project", "hours": 2, "description": "This course is for participants in year 2 of the Grand Challenges program. Students will organize into small teams of 4-8 student to pursue research and development projects that were approved and funded in year 1. Participating students can also propose new projects."},
  "GT 2500": {"name": "ThinkBig@Tech", "hours": 0, "description": "ThinkBig@Tech are faculty led Living Learning Communities. Students participating in these programs will be engaging closely with faculty. The topic of each Living Learning Community is based on the faculty interests, and students sign up for the one they are interested in."},
  "GT 2694": {"name": "Undergraduate Internship", "hours": 1, "description": "Undergraduate Internship for which the student is paid, Freshmen and Sophomores only."},
