  "GT 4813": {"name": "Project in Energy Systems", "hours": 3, "description": "Multidisciplinary project in the area of energy systems. Open to students completing the minor in Energy Systems. Students must have completed or be on track to complete all requriements for the energy systems minor except this course."},
  "GT 4903": {"name": "Special Problems", "hours": 1, "description": "Multi-disciplined research topic selected in consultation with advisor. A brief description, endorsed by the faculty advisor(s)."},
  "GT 6000": {"name": "Grad Groups Extended Orientation", "hours": 1, "description": "Georgia Tech\u2019s extended-orientation program for first-semester graduate students promoting a positive student experience through social interaction, familiarization with campus resources, and peer mentorship."},
