  "HTS 4011": {"name": "Seminar in Sociology", "hours": 4, "description": "Advanced undergraduate topics in sociology. Designed for HTS majors, but open to other students with junior or senior standing."},
  "HTS 4031": {"name": "Seminar in European History", "hours": 4, "description": "Advanced undergraduate topics in European history. Designed for HTS majors, but open to other students with junior or senior standing."},
  "HTS 4081": {"name": "Seminar in History of Technology", "hours": 4, "description": "Advanced undergraduate topics in the history of technology. Designed for HTS majors, but open to other students with junior or senior standing."},
  "HTS 4086": {"name": "Seminar in Health, Medicine, and Society", "hours": 4, "description": "Advanced undergraduate topics in health and medicine. Designed for HTS majors and HMS minors, but open to other students with junior or senior standing."},
