  "HTS 7001": {"name": "Foundations of Socio-historical Analysis", "hours": 3, "description": "Introduces key concepts and methods used in the historical analysis of social phenomena."},
  "HTS 7999": {"name": "Comprehensive Exam Preparation", "hours": 3, "description": "Preparation for comprehensive exam in fields of history or sociology."},
