  "IAC 2001": {"name": "Global Religions and Community Engagement", "hours": 3, "description": "This course prepares students for leadership in a multi-faith society through the study of global religions and active engagement with diverse religious communities of Atlanta."},
  "IAC 2002": {"name": "Science, Engineering, and Religion: An Interfaith Dialogue", "hours": 3, "description": "This course gathers diverse students serious about faith to explore topics at the intersection of science, engineering, and religion."},
