  "ID 2021": {"name": "Industrial Design Studio 1", "hours": 4, "description": "This course provides an introduction to the design process on visual principles and presentation techniques with a focus on sketching and modeling techniques related to 3D form."},
  "ID 2022": {"name": "Industrial Design Studio 2", "hours": 4, "description": "This course applies more structured design methods to research and exploration of product form and function and introduces concepts of universal design and user centered design."},
  "ID 2023": {"name": "Industrial Design Studio 1", "hours": 3, "description": "This course applied structured design methods to research and exploration of product form and function and introduces concepts of user centered design."},
  "ID 2024": {"name": "Industrial Design Studio 2", "hours": 3, "description": "This course applies structured user-centered design methods to research and exploration of product design and function, and introduces concepts of universal design."},
  "ID 2101": {"name": "Digital Design Methods", "hours": 3, "description": "This course introduces the basics of product design in the CAD environment. Stuents design a product, apply 3D scanning, produce an animation and 3D print."},
  "ID 2102": {"name": "3D Modeling", "hours": 2, "description": "This course introduces 3D modeling methods for solid and surface modeling in CAD software. Students create multi-component assembly drawings and explore rendering techniques for product design."},
  "ID 2202": {"name": "History of Modern Industrial Design", "hours": 3, "description": "History and development of industrial design from the beginning of the Industrial Revolution to the present."},
  "ID 2241": {"name": "History of Art 1", "hours": 3, "description": "This course surveys art from Prehistory through the Renaissance and is organized around stylistic periods that are arranged chronologically. Classes will consist of lectures with slides that focus on these stylistic periods."},
  "ID 2242": {"name": "History of Art 2", "hours": 3, "description": "This course surveys the major artistic movements and aesthetics of the 17th, 18th, 19th, 20th, and early 21st centuries in painting, sculpture and architecture."},
  "ID 2320": {"name": "Human Factors in Design", "hours": 3, "description": "This course examines the theory of Human Factors to provide a working knowledge of the physical and cognitive attributes of people that designers must accomodate."},
  "ID 2325": {"name": "User Centered Design Methods", "hours": 3, "description": "This course introduces students to user-centric design methods used to identify, understand, assess and prioritize the neuroscience factors and perceptions that contribute to more effective product design and human-centered design solutions."},
  "ID 2401": {"name": "Visual Design Thinking", "hours": 3, "description": "Introduction to techniques to help designers build a vocabulary to support effective visual communication including fundamentals of layout, sketching, rendering, schematics, information graphics &amp; storyboarding."},
  "ID 2510": {"name": "Introduction to Smart Product Design", "hours": 3, "description": "This course provides an introduction to smart product design including the basics of sensor technologies, electronics and programming required to produce working product concept prototypes."},
  "ID 2698": {"name": "Undergraduate Research Assistantship", "hours": 1, "description": "Independent research conducted under the guidance of a faculty member."},
