  "ID 3031": {"name": "Health Design Studio 1", "hours": 4, "description": "The application of systematic user-centered design methods and research to projects focused on the design development of new and/or improved health-related products with an emphasis on inclusive design."},
  "ID 3032": {"name": "Health Design Studio 2", "hours": 4, "description": "The application of systematic user-centered design methods and research to projects focused on the design development of new and/or improved health-related products with an emphasis on products and product systems."},
  "ID 3041": {"name": "Product Development Studio 1", "hours": 4, "description": "The application of systematic user-centered design methods and research to projects focused on the use of parametric design and CNC capabilities in the design development of products, services &amp; systems."},
  "ID 3042": {"name": "Product Development Studio 2", "hours": 4, "description": "The application of systematic user-centered design methods to projects focused on the design development of 'real-world' products, services, interfaces &amp; systems in collaboration with external sponsors."},
  "ID 3051": {"name": "Interactive Product Design Studio 1", "hours": 4, "description": "The application of systematic product design and research methods to projects focused on new applications of sensor-based technologies to the creation of interactions, products and interfaces with an emphasis on the importance of user-centered design."},
  "ID 3052": {"name": "Interactive Product Design Studio 2", "hours": 4, "description": "The application of systematic user-centered design methods to projects focused on new applications of sensor-based technologies with an emphasis on interactive environments, interfaces, navigation and mobility."},
  "ID 3103": {"name": "Industrial Design Computing I", "hours": 3, "description": "Introduction to 2-D computer drawing systems."},
  "ID 3104": {"name": "Industrial Design Computing II", "hours": 3, "description": "Introduction to 3-D modeling systems."},
  "ID 3201": {"name": "Design &amp; Community: The Social and Environmental Impact of Design", "hours": 3, "description": "Students explore socially and environmentally responsible industrial design practices at home and abroad, and partner with local organizations to develop community-based design projects."},
  "ID 3301": {"name": "Materials I: Renewables", "hours": 3, "description": "This course examines the characteristics, production technologies, histories, and environmental impacts of nine categories of renewable materials familiar to product and product system design."},
  "ID 3302": {"name": "Materials and Processes II: Nonrenewables", "hours": 3, "description": "Examination of characteristics, production technologies, histories, and environmental impacts of nonrenewable materials used in product design."},
  "ID 3320": {"name": "Design Methods: User Centered Design", "hours": 3, "description": "This course introduces students to current user-centric design methods used to identify, understand, assess and prioritize the factors and perceptions that contribute to more effective product design and human-centered design solutions."},
  "ID 3510": {"name": "Introduction to Interactive Product Design", "hours": 3, "description": "This course provides an introduction to interactive product design including the basics of sensor technologies, electronics and programming required to produce working product concept prototypes."},
  "ID 3803": {"name": "Special Topics", "hours": 3, "description": "Topics of current interest in industrial design."},
  "ID 3813": {"name": "Special Topics", "hours": 3, "description": "Topics of current interest in Industrial Design."},
