  "ID 4833": {"name": "Special Topics: Collaborative", "hours": 3, "description": "Application of the design process to advanced multidisciplinary problems by a team. Projects from a range of interest areas: consumer, industrial products, transportation, furniture."},
  "ID 4843": {"name": "Special Topics: History and Theory", "hours": 3, "description": "Special topics in history and theory not included in the professional curriculum."},
