  "PHYS 4823": {"name": "Special Topics", "hours": 3, "description": "Courses in special topics of current interest in physics are presented from time to time."},
  "PHYS 4833": {"name": "Special Topics", "hours": 3, "description": "Courses in special topics of current interest in physics are presented from time to time."},
  "PHYS 4854": {"name": "Special Topics", "hours": 4, "description": "Courses in special topics of current interest in physics are presented from time to time."},
